    net: { input: "đầu vào", hidden: "các lớp ẩn", output: "đầu ra", flow: "các con số đi theo hướng này", guess: "dự đoán", right: "đáp án đúng", nudge: "chỉnh nhẹ mọi trọng số", repeat: "đoán, kiểm tra, chỉnh, lặp lại" },
