      tasks: ["viết", "tóm tắt", "trích xuất thông tin", "trò chuyện", "trả lời câu hỏi", "tạo hình ảnh"],
      online: "dùng qua mạng", onlineSub: "trong ứng dụng, dịch vụ", local: "tự chạy trên máy", localSub: "một số tải về miễn phí",
